@prefix ex: <http://example.org/> .
@prefix ns3: <http://example.org/ns3/> .
@prefix schema: <https://schema.org/> .
@prefix ns2: <http://example.org/ns2/> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .

ex:antakya a schema:AdministrativeArea ;
    rdfs:label "Antakya" ;
    ns3:P89i_contains ex:turkey .

ex:kurt_reinhard a ns3:P21_Person ;
    rdfs:label "Kurt Reinhard" ;
    ns3:P1i_identifies ex:reinhard_1975 .

ex:düdük a ns2:CACAO_0000025 ;
    rdfs:label "düdük" .

ex:germany a schema:Country ;
    rdfs:label "Germany" .

ex:mehmet_bayraktar a ns3:E21_Person ;
    rdfs:label "Mehmet Bayraktar" ;
    ns3:P102_has_title ex:karakoyun .

ex:karakoyun a ns3:E35_Title ;
    rdfs:label "Karakoyun" .

ex:turkey a schema:Country ;
    rdfs:label "Turkey" .

ex:central_asia a schema:AdministrativeArea ;
    rdfs:label "Central Asia" .

ex:reinhard_1975 a ns3:E41_Appellation ;
    rdfs:label "Reinhard 1975" .

ex:event_1956 a schema:Event ;
    schema:date "1956" ;
    schema:location ex:antakya ;
    schema:agent ex:kurt_reinhard, ex:mehmet_bayraktar ;
    schema:description "On a warm spring evening in the year 1956, the governor ('vali' of Antakya (southeast Turkey), Kurt Reinhard, and I were sitting at dinner and wondering what music one could document the next day." .

ex:flute_duduk a ns2:CACAO_0000025 ;
    rdfs:label "flute düdük" ;
    schema:instrumentPlayedBy ex:mehmet_bayraktar .

ex:vali a ns3:P21_Person ;
    rdfs:label "vali" ;
    schema:agentOf ex:event_1956 .

ex:loam_house a schema:House ;
    schema:occupant ex:mehmet_bayraktar .

ex:recorded_songs_dances a schema:CreativeWork ;
    rdfs:label "recorded series of songs and dances" ;
    schema:creator ex:mehmet_bayraktar ;
    schema:learningSource ex:mehmet_bayraktar_father .

ex:mehmet_bayraktar_father a ns3:P21_Person ;
    rdfs:label "Mehmet Bayraktar's father" ;
    schema:occupation "nomad" ;
    schema:hasHerd ex:sheep_herd .

ex:sheep_herd a schema:Herd ;
    schema:animal "sheep" ;
    schema:owner ex:mehmet_bayraktar_father ;
    schema:season "spring", "fall" ;
    schema:habitat ex:cool_pastures_mountains, ex:lowlands_by_sea .

ex:cool_pastures_mountains a schema:Place ;
    rdfs:label "cool pastures of the mountains" .

ex:lowlands_by_sea a schema:Place ;
    rdfs:label "lowlands by the sea" ;
    schema:climate "mild winter climate" .

ex:duct_flute_duduk a ns2:CACAO_0000025 ;
    rdfs:label "duct flute düdük" ;
    schema:instrumentPlayedBy ex:mehmet_bayraktar ;
    schema:availability "anywhere and in any size at that time" .

ex:recorder_seven_finger_holes a ns2:CACAO_0000025 ;
    rdfs:label "recorder with seven finger holes and one thumb hole" ;
    schema:instrumentPlayedBy ex:mehmet_bayraktar ;
    schema:numberOfFingerHoles "7" ;
    schema:numberOfThumbHoles "1" .

ex:circular_breathing a schema:Technique ;
    rdfs:label "circular breathing" ;
    schema:description "continuous stream of air into the instrument through a simultaneous inhale (through the nose) and exhale (through the mouth)" ;
    schema:usedBy ex:mehmet_bayraktar .

ex:karakoyun_song a schema:MusicComposition ;
    rdfs:label "Karakoyun" ;
    schema:genre "instrumental narrative" ;
    schema:about "nomadic piece" ;
    schema:audience "herders", "farmers", "townsfolk" ;
    schema:performancePlace ex:turkey, ex:central_asia .

ex:instrumental_narrative_turkey a schema:MusicGenre ;
    rdfs:label "instrumental narrative in Turkey" ;
    schema:performanceFrequency "frequently performed", "increasingly seldomness today" ;
    schema:hasCharacteristic "instrumental improvisation" .

ex:instrumental_narrative_central_asia a schema:MusicGenre ;
    rdfs:label "instrumental narrative in Central Asia" ;
    schema:preservationStatus "preserved on a large scale" ;
    schema:hasCharacteristic "musical imagery" .

ex:shepherd_story a schema:Story ;
    rdfs:label "Shepherd's Story" ;
    schema:mainEntity ex:shepherd, ex:agas_daughter ;
    schema:plot "shepherd loved the daughter of a rich, respected man, an 'aga, who did not want to give him the girl as his wife, but also did not want to turn him coldly away. So he set up a condition, which he assumed, the boy would not be able to fulfill. The shepherd should lock up his sheep for a week, and should only let them lick salt, but should not lead them to water. And then, when he had let the herd free, he should succeed in preventing the sheep from running to the water, despite their great thirst. The young shepherd agreed to this condition, and when a week was up, he played such a lovely melody on his flute that the sheep stayed with him and listened. He had passed the test and received the daughter of the aga as his wife." .

ex:shepherd a schema:Person ;
    rdfs:label "shepherd" ;
    schema:hasRelationship ex:agas_daughter .

ex:agas_daughter a schema:Person ;
    rdfs:label "daughter of an aga" ;
    schema:parent ex:aga .

ex:aga a schema:Person ;
    rdfs:label "aga" ;
    schema:description "rich, respected man" .

ex:salt_licking_test a schema:Event ;
    rdfs:label "salt licking test" ;
    schema:participant ex:shepherd, ex:sheep_herd ;
    schema:duration "one week" ;
    schema:outcome "passed" .

ex:magical_power_music a schema:Belief ;
    rdfs:label "original belief in the magical power of music" ;
    schema:heldBy ex:shepherds, ex:nomads ;
    schema:source ex:reinhard_1975_text .

ex:reinhard_1975_text a schema:CreativeWork ;
    rdfs:label "Reinhard 1975:124" ;
    schema:citation "Reinhard 1975:124" .
